import * as issueService from "@/server/services/issue-service";
import * as commentService from "@/server/services/comment-service";
import "@/server/services/notification-service";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

beforeAll(async () => { await useTemporaryDatabase(); });

it("smoke", async () => {
  const t = await createTenant("abs-smoke");
  const past = new Date(Date.now() - 3600e3).toISOString();
  const fut = new Date(Date.now() + 3600e3).toISOString();
  const a = await memberService.setAbsence(t.actors.member, {
    orgId: t.org.id, userId: t.userIds.member, delegateUserId: t.userIds.viewer,
    startsAt: past as never, endsAt: fut as never, note: "hi",
  });
  console.log(a);
  expect(await memberService.getAbsence(t.actors.viewer, t.org.id, t.userIds.member)).toEqual(a);
  const issue = await issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }));
  expect(issue.assigneeId).toBe(t.userIds.viewer);
  const own = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { assigneeId: t.userIds.member }));
  expect(own.assigneeId).toBe(t.userIds.member);
  await commentService.createComment?.(t.actors.owner, { orgId: t.org.id, issueId: own.id, body: "hey", parentId: null, mentionedUserIds: [t.userIds.member] } as never);
  const n = await notificationRepo.listNotifications({ orgId: t.org.id, recipientId: t.userIds.viewer, limit: 50, cursor: null } as never);
  console.log(n.items.map((x) => x.kind));
  const m = await memberRepo.findMember(t.org.id, t.userIds.viewer);
  await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m!.id });
  expect((await memberService.getAbsence(t.actors.owner, t.org.id, t.userIds.member))?.delegateUserId).toBeNull();
  await expect(memberService.setAbsence(t.actors.member, { orgId: t.org.id, userId: t.userIds.admin, delegateUserId: null, startsAt: past as never, endsAt: fut as never, note: null })).rejects.toThrow(/denied/);
});
